package com.example.lending.adapter.in.web;

import com.example.lending.domain.BookAlreadyOnLoanException;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.LoanAlreadyReturnedException;
import com.example.lending.domain.LoanLimitExceededException;
import com.example.lending.domain.LoanNotFoundException;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.Map;

@RestControllerAdvice
public class WebExceptionHandler {

    @ExceptionHandler(BookAlreadyOnLoanException.class)
    public ProblemDetail handleAlreadyOnLoan(BookAlreadyOnLoanException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }

    @ExceptionHandler(LoanLimitExceededException.class)
    public ResponseEntity<Map<String, String>> handleLoanLimitExceeded(LoanLimitExceededException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "LOAN_LIMIT_EXCEEDED"));
    }

    @ExceptionHandler(LoanAlreadyReturnedException.class)
    public ResponseEntity<Map<String, String>> handleAlreadyReturned(LoanAlreadyReturnedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "ALREADY_RETURNED"));
    }

    @ExceptionHandler(LoanNotFoundException.class)
    public ProblemDetail handleLoanNotFound(LoanNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(BookNotFoundException.class)
    public ProblemDetail handleNotFound(BookNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(MemberNotFoundException.class)
    public ProblemDetail handleMemberNotFound(MemberNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(IllegalArgumentException.class)
    public ProblemDetail handleInvalidInput(IllegalArgumentException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, e.getMessage());
    }
}

